function formatDateKey(year, monthIndex, day) {
    const m = String(monthIndex + 1).padStart(2, '0');
    const d = String(day).padStart(2, '0');
    return `${year}-${m}-${d}`;
}

function formatIndoDate(dateStr) {
    if (!dateStr) return '-';
    const parts = dateStr.split('-');
    if (parts.length !== 3) return dateStr;
    const y = parts[0];
    const m = parseInt(parts[1], 10) - 1;
    const d = parseInt(parts[2], 10);
    return `${d} ${monthNamesIndo[m]} ${y}`;
}

function escapeHTML(str) {
    return str.replace(/[&<>'"]/g, 
        tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
    );
}

// EXPORT FUNCTIONS
function exportExcel() {
    const currentPeriodAgendas = getAgendasForCurrentPeriod();

    if (currentPeriodAgendas.length === 0) {
        showToast('Tidak ada agenda pada periode ini untuk diexport.', 'error');
        return;
    }

    const exportData = currentPeriodAgendas.map(item => {
        const dateStr = item.startDate === item.endDate 
            ? formatIndoDate(item.startDate) 
            : `${formatIndoDate(item.startDate)} s/d ${formatIndoDate(item.endDate)}`;

        return {
            "Nama Agenda": item.title,
            "Tanggal / Range Tanggal": dateStr,
            "Keterangan": item.description || '-'
        };
    });

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Agenda Pendidikan");

    worksheet['!cols'] = [
        { wch: 35 },
        { wch: 30 },
        { wch: 40 }
    ];

    const fileName = viewMode === 'masehi' 
        ? `Agenda_Kaldik_Masehi_${currentYear}.xlsx`
        : `Agenda_Kaldik_TA_${currentYear}_${currentYear+1}.xlsx`;

    XLSX.writeFile(workbook, fileName);
    showToast('Export Excel berhasil diunduh.');
}

function exportHTML() {
    const titleStr = viewMode === 'masehi' 
        ? `Kalender Masehi Tahun ${currentYear}`
        : `Kalender Pendidikan Tahun Ajaran ${currentYear}/${currentYear + 1}`;

    const tempContainer = document.getElementById('printableArea').cloneNode(true);
    tempContainer.querySelectorAll('.today').forEach(el => el.classList.remove('today'));
    tempContainer.querySelectorAll('.no-print').forEach(el => el.remove());

    const htmlContent = `
<!DOCTYPE html>
<html lang="id">
<head>
<meta charset="UTF-8">
<title>${titleStr}</title>
<style>
* { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; color-adjust: exact !important; }
body { font-family: 'Inter', system-ui, sans-serif; padding: 20px; color: #0f172a; }
h2 { text-align: center; margin-bottom: 20px; }
.calendar-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; }
.month-card { border: 1px solid #cbd5e1; border-radius: 8px; overflow: hidden; page-break-inside: avoid; }
.month-header { background: #f1f5f9; padding: 8px; font-weight: bold; display: flex; justify-content: space-between; }
.month-days-header { display: grid; grid-template-columns: repeat(7, 1fr); text-align: center; font-size: 12px; font-weight: bold; padding: 4px 0; border-bottom: 1px solid #e2e8f0; }
.month-days-header div:first-child { color: #ef4444; }
.month-days-grid { display: grid; grid-template-columns: repeat(7, 1fr); padding: 4px; gap: 2px; }
.calendar-day { min-height: 38px; padding: 3px; font-size: 12px; display: flex; flex-direction: column; align-items: center; }
.calendar-day.sunday { color: #af0d0d; font-weight: bold; }
.day-badges { width: 100%; display: flex; flex-direction: column; gap: 2px; margin-top: auto; }
.event-badge-bar { height: 2px; width: 100%; border-radius: 1px; display: block; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
.badge-color-preview { width: 16px; height: 16px; border-radius: 50%; display: inline-block; vertical-align: middle; -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
.agenda-section { margin-top: 30px; }
table { width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 13px; }
th, td { border: 1px solid #cbd5e1; padding: 8px; text-align: left; }
th { background: #f1f5f9; }
</style>
</head>
<body>
${tempContainer.innerHTML}
</body>
</html>`;

    const blob = new Blob([htmlContent], { type: 'html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${titleStr.replace(/ /g, '_')}.html`;
    a.click();
    URL.revokeObjectURL(url);
    showToast('File HTML berhasil diexport.');
}
